/**
 * Runs migrations with Kysely's Migrator.
 *
 * drizzle-kit still writes the SQL (`npm run db:generate`), so the Drizzle
 * schema stays the source of truth and CI can check it against the migrations.
 * Kysely only runs them:
 *
 *   up:   drizzle/<tag>.sql        (generated by drizzle-kit)
 *   down: drizzle/down/<tag>.sql   (written by hand)
 *
 * Migrations come from drizzle-kit's journal and run in name order
 * (0000_…, 0001_…). Kysely records each one by name in kysely.kysely_migration,
 * runs everything pending in one transaction under a lock, and refuses to run
 * if an applied migration is missing or a new one sorts before the last
 * applied one, instead of skipping it.
 *
 * A migration without a down file can't be rolled back: rolling it back
 * throws, rather than Kysely's default of forgetting it without undoing it.
 * The baseline has no down file on purpose; reset a local database instead.
 */
import { existsSync, readFileSync } from "node:fs"
import path from "node:path"
import { Kysely, Migrator, sql as kyselySql, type Migration, type MigrationProvider } from "kysely"
import { PostgresJSDialect } from "kysely-postgres-js"
import type { Sql } from "postgres"
import { MIGRATIONS_DIR, readJournal } from "./migrations"

/** Kysely's bookkeeping lives outside `public`, so Supabase's API doesn't expose it. */
export const MIGRATION_SCHEMA = "kysely"
export const MIGRATION_TABLE = "kysely_migration"

export const upFile = (tag: string, dir = MIGRATIONS_DIR) => path.join(dir, `${tag}.sql`)
export const downFile = (tag: string, dir = MIGRATIONS_DIR) => path.join(dir, "down", `${tag}.sql`)

/** Splits on drizzle-kit's `--> statement-breakpoint` markers, one statement per query. */
export function splitStatements(text: string): string[] {
  return text
    .split("--> statement-breakpoint")
    .map((s) => s.trim())
    .filter((s) => s.replace(/--.*$/gm, "").trim() !== "")
}

async function runFile(db: Kysely<unknown>, file: string) {
  for (const statement of splitStatements(readFileSync(file, "utf8"))) {
    await kyselySql.raw(statement).execute(db)
  }
}

export class SqlFileMigrationProvider implements MigrationProvider {
  /** `dir` is a drizzle-kit output folder; tests point it at a fixture. */
  constructor(private readonly dir = MIGRATIONS_DIR) {}

  async getMigrations(): Promise<Record<string, Migration>> {
    const migrations: Record<string, Migration> = {}
    for (const { tag } of readJournal(this.dir)) {
      const down = downFile(tag, this.dir)
      migrations[tag] = {
        up: (db) => runFile(db, upFile(tag, this.dir)),
        down: async (db) => {
          if (!existsSync(down)) {
            throw new Error(`${tag} can't be rolled back: drizzle/down/${tag}.sql doesn't exist.`)
          }
          await runFile(db, down)
        },
      }
    }
    return migrations
  }
}

/**
 * Wraps a postgres.js connection in Kysely and a Migrator.
 * The caller owns `sql` and closes it; `db.destroy()` would close it too.
 */
export function createMigrator(sql: Sql, dir = MIGRATIONS_DIR) {
  const db = new Kysely<unknown>({ dialect: new PostgresJSDialect({ postgres: sql }) })
  const migrator = new Migrator({
    db,
    provider: new SqlFileMigrationProvider(dir),
    migrationTableSchema: MIGRATION_SCHEMA,
    migrationTableName: MIGRATION_TABLE,
  })
  return { db, migrator }
}

/** Throws the migrator's error, naming the migration that failed. */
export function throwIfFailed(result: Awaited<ReturnType<Migrator["migrateToLatest"]>>) {
  if (!result.error) return
  const failed = result.results?.find((r) => r.status === "Error")
  const err = result.error instanceof Error ? result.error : new Error(String(result.error))
  if (failed) err.message = `${failed.migrationName} (${failed.direction.toLowerCase()}) failed: ${err.message}`
  throw err
}
